<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class TravelBooking extends Model { protected $fillable=['business_id','vehicle_id','route_id','user_id','customer_name','customer_phone','pickup','destination','travel_date','travel_time','passengers','status','quoted_amount','notes']; protected $casts=['travel_date'=>'date','quoted_amount'=>'float']; public function vehicle(){return $this->belongsTo(TravelVehicle::class,'vehicle_id');} public function route(){return $this->belongsTo(TravelRoute::class,'route_id');} public function business(){return $this->belongsTo(Business::class);} }
